package com.railway.util;
import java.io.Console;import java.sql.*;
/** One-time CLI utility. Set DB_URL, DB_USER, DB_PASSWORD first; no credentials are embedded. */
public class CreateAdmin {public static void main(String[] args)throws Exception{Console console=System.console();if(console==null)throw new IllegalStateException("Run from a real terminal so password input is not echoed.");String name=console.readLine("Admin full name: "),email=console.readLine("Admin email: "),phone=console.readLine("Admin phone: ");char[] chars=console.readPassword("Admin password (10-72 chars): ");String password=new String(chars);java.util.Arrays.fill(chars,'\0');if(password.length()<10||password.length()>72||!Validation.email(email)||!Validation.phone(phone)||!Validation.name(name))throw new IllegalArgumentException("Invalid admin details");try(Connection c=DB.getConnection();PreparedStatement p=c.prepareStatement("INSERT INTO users(full_name,email,phone,password_hash,role) VALUES(?,?,?,?, 'ADMIN')")){p.setString(1,name);p.setString(2,email.toLowerCase());p.setString(3,phone);p.setString(4,Passwords.hash(password));p.executeUpdate();System.out.println("Admin account created.");}}}
